E["46:af28999e"] = "Вивчіть професію - її наступний крок з'явиться тут."
E["46:c5846b96"] = "Перезавантажити інтерфейс зараз, щоб змінити стиль?"
E["46:d974ba13"] = "Натисніть зірку біля майстра, щоб залишити його тут."
E["47:0f854489"] = "Рідкісні додаткові знахідки з цих жил - наведіть на кожну."
E["47:1f645ecf"] = "Майстри, які знають рецепт, роблять вам пропозицію."
E["47:1fd330ab"] = "Клік: усі способи здобути це в Кодекс > Матеріали"
E["47:4ca1267b"] = "Прохань ще немає - натисніть «Попросити про це» на сторінці майстра."
E["47:67e1222e"] = "Майстри, яких ви додасте до обраного, з'являться тут."
E["47:68e5e4a5"] = "кнопка на мінікарті в збирачах кнопок мінікарти"
E["47:b1682364"] = "Ви можете це зробити - матеріалів немає у ваших сумках."
E["47:b7ad9b7a"] = "Спершу відкрийте вкладку «Надіслати лист», потім натисніть знову."
E["47:bcd7a082"] = "Немає для вашої фракції в даних Wowhead Forever"
E["47:c438530e"] = "Перезавантажити інтерфейс зараз, щоб зміна набула чинності?"
E["47:cd87c04c"] = "Запитано - вони отримають вікно, щоб прийняти або відхилити."
E["48:0187656c"] = "Shift-клік, щоб відстежувати матеріали цього кроку"
E["48:1f216021"] = "Його не можна розчаклувати - враховується найбільше золото."
E["48:38b2f64b"] = "Подобається додаток? Пожертва допомагає йому розвиватися."
E["48:5f298b66"] = "Зроблено вами - має вартість своїх матеріалів"
E["48:74af505f"] = "Увійдіть цим персонажем один раз, щоб побачити його сумки."
E["48:9d89ae3d"] = "Обраних ще немає - натисніть зірку біля майстра."
E["48:a20a2e0e"] = "Вивчіть «Підмайстер» зараз (рівень 10) у будь-якого наставника"
E["48:a2fbae9f"] = "Жоден гравець Mastercraft у мережі зараз цього не вміє."
E["48:c3cbcf2d"] = "Креслення у ваших сумках - клацніть правою кнопкою, щоб вивчити"
E["48:dcb34d26"] = "Помилок не зафіксовано - усе працює справно."
E["48:f60954a4"] = "Не приєднано: очікування чат-каналів гри"
E["48:fb79b14f"] = "Ще не вивчено. Навчає: Учитель Рибальства"
E["48:fbc47d30"] = "Ваше золото з'явиться тут день за днем, починаючи з сьогодні."
